# Viva — slot D5 (part B): hair & nail disorders (7 cases)
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — hair chapter (classify alopecias,
# trichotillomania, alopecia areata, telogen/anagen effluvium, evaluation of hair loss, AGA, drugs and hair,
# cicatricial alopecias, hair shaft defects), hair cycle/anatomy, nail chapter (nail anatomy, skin diseases with nail
# changes, nail pitting, yellow nail syndrome, ingrown toenail), anti-androgens; facts checked with IADVL 5e.
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Alopecia areata", src=f"{PYQ}; {IA} (Alopecia areata); SALT score; JAK inhibitor approvals",
 qa=[
 ("Define alopecia areata (AA).", ["Chronic, relapsing, immune-mediated, non-scarring hair loss with well-circumscribed patches of hair loss on scalp or any hair-bearing area, with preserved follicular openings; affects ~2% lifetime; any age, peak 20–40 y"]),
 ("Classify alopecias (PYQ).", ["Non-scarring (non-cicatricial): AA, androgenetic alopecia, telogen effluvium, anagen effluvium, trichotillomania, traction (early), tinea capitis (non-inflammatory), secondary syphilis, hair shaft defects, hypothyroidism, nutritional", "Scarring (cicatricial) — primary: lymphocytic (DLE, LPP, frontal fibrosing alopecia, central centrifugal cicatricial alopecia, pseudopelade of Brocq), neutrophilic (folliculitis decalvans, dissecting cellulitis), mixed (acne keloidalis, erosive pustular dermatosis); secondary: burns, radiation, trauma, kerion, tumours, morphoea, infections (lupus vulgaris)"]),
 ("Describe the hair cycle (PYQ).", ["Anagen (growth): 2–7 years, ~85–90% of scalp hairs, determines length", "Catagen (regression): 2–3 weeks, ~1%", "Telogen (rest): ~3 months, 10–15%; club hair shed in exogen", "Kenogen: empty follicle interval; scalp has ~100,000 hairs, normal shedding 50–100/day; growth ~1 cm/month"]),
 ("Pathogenesis of AA.", ["Collapse of immune privilege of anagen hair bulb (reduced MHC I, TGF-β, α-MSH) → autoreactive CD8+NKG2D+ T cells attack follicular autoantigens (melanocyte/keratinocyte), IFN-γ and IL-15 via JAK–STAT signalling → follicle forced into dystrophic anagen/telogen; follicle stem cells spared (non-scarring, reversible)", "Genetic (HLA-DQB1, ULBP, CTLA4, IL2RA), family history 10–20%, stress, viral infections, vaccination triggers", "Associations: atopy, thyroid autoimmunity, vitiligo, Down syndrome, APECED, lupus, diabetes, iron deficiency"]),
 ("Clinical patterns and signs.", ["Patchy (commonest), ophiasis (band along occipital and temporal margins — poor prognosis), sisaipho (inverse ophiasis — frontoparietal), diffuse (acute diffuse and total alopecia — mimics TE), alopecia totalis (whole scalp), universalis (all body hair), reticular", "Exclamation-mark hairs (tapering proximal ends) at active edge, positive pull test at margin, regrowth with white (vellus) hairs first, sparing of grey hairs ('sudden whitening overnight')", "Nails (10–60%): fine regular geometric pitting, trachyonychia, Beau's lines, red lunulae, onychomadesis"]),
 ("Trichoscopy in AA.", ["Yellow dots (keratin in empty follicles), black dots (cadaverised hairs — active), exclamation-mark hairs, broken hairs, tapered hairs, short vellus/regrowing hairs, Pohl–Pinkus constrictions"]),
 ("Histopathology.", ["Peribulbar lymphocytic infiltrate ('swarm of bees') around anagen bulbs (acute), increased catagen/telogen hairs, miniaturised follicles, fibrous streamers, pigment casts, eosinophils; no scarring"]),
 ("Severity assessment.", ["SALT score (Severity of Alopecia Tool): % scalp hair loss — vertex 40%, posterior 24%, each side 18% — S1 <25%, S2 25–49, S3 50–74, S4 75–99, S5 100%; severe AA = SALT ≥50", "Alopecia areata investigator global assessment (AA-IGA)"]),
 ("Differential diagnosis.", ["Tinea capitis (scaling, broken hairs, KOH), trichotillomania (bizarre shapes, broken hairs of varying length, no exclamation-mark hairs, trichoscopy — flame hairs, tulip hairs, V-sign), telogen effluvium (diffuse, positive pull test everywhere), secondary syphilis (moth-eaten), androgenetic alopecia (diffuse AA), early scarring alopecia, traction alopecia, loose anagen syndrome, temporal triangular alopecia (congenital)"]),
 ("Investigations.", ["Clinical/trichoscopy; thyroid function and antibodies, CBC, ferritin, vitamin D, blood sugar; VDRL if moth-eaten; KOH; biopsy if doubtful"]),
 ("Treatment.", ["Limited patchy (<50%): intralesional triamcinolone acetonide 2.5–10 mg/ml (5 mg/ml commonly) every 4–6 weeks (first line in adults), super-potent topical steroids (children), minoxidil 5% adjunct, topical immunotherapy for chronic (DPCP, SADBE — induce allergic contact dermatitis), anthralin short contact (children)", "Extensive/rapidly progressive: oral mini-pulse betamethasone/dexamethasone 5 mg twice weekly, pulse methylprednisolone, short oral prednisolone; methotrexate (± low-dose steroid), azathioprine, cyclosporine, oral minoxidil", "JAK inhibitors for severe AA (SALT ≥50): baricitinib 4 mg (FDA 2022, adults; approved in India), ritlecitinib 50 mg (≥12 y), deuruxolitinib; tofacitinib off-label — monitor CBC, lipids, LFT, infections (TB/HZV screening)", "Supportive: wigs, hair pieces, eyebrow tattooing/microblading, counselling, support groups"]),
 ("Prognosis.", ["~50% of limited patchy AA regrow within a year without treatment; poor prognostic factors — onset in childhood, extensive (totalis/universalis), ophiasis, long duration (>1 y), nail changes, atopy, family history, associated autoimmunity, Down syndrome"]),
 ],
 spot=["Smooth round patch with exclamation-mark hairs — AA", "Yellow dots, black dots on trichoscopy", "Severe AA — baricitinib/ritlecitinib"]),

dict(case="Paronychia", src=f"{PYQ}; {IA} (Nail disorders)",
 qa=[
 ("Describe the anatomy of the nail unit (PYQ).", ["Nail plate (hard keratin produced by the matrix), proximal nail fold with cuticle (eponychium — seals the space), lateral nail folds, nail matrix (proximal — forms dorsal plate; distal — forms ventral plate; lunula is the visible distal matrix), nail bed (adheres to plate, longitudinal ridges, rich vasculature), hyponychium (beneath free edge), onychodermal band", "Growth: fingernails ~3 mm/month (replace in 6 months), toenails ~1 mm/month (12–18 months)"]),
 ("Define acute and chronic paronychia.", ["Acute: painful bacterial infection of the nail fold (S. aureus, Streptococcus, Pseudomonas; HSV — herpetic whitlow) after trauma, hangnail, nail biting, manicure, ingrown nail — red, hot, swollen, tender fold, pus", "Chronic: inflammation of proximal nail fold >6 weeks with loss of cuticle, rounded bolstered red fold, intermittent discharge, transverse ridging/dystrophy of nail — wet work (housewives, cooks, bartenders), diabetes, contact irritants/allergens, Candida colonisation (secondary)", "Drug-induced paronychia with pyogenic granuloma: isotretinoin, EGFR inhibitors, taxanes, antiretrovirals (indinavir)"]),
 ("Differentiate bacterial and fungal chronic paronychia (PYQ).", ["Bacterial: acute onset, severe pain, throbbing, pus, rapid course, single digit, Gram-positive cocci", "Candidal/chronic: insidious, mild pain/itch, no frank pus, loss of cuticle, several fingers, wet workers, KOH yeast, nail plate ridging and discolouration (greenish-black — Pseudomonas co-infection)"]),
 ("Management of acute paronychia.", ["Warm soaks (water or dilute vinegar/antiseptic) 3–4 times daily; topical mupirocin/fusidic acid", "Oral antibiotics (cloxacillin, cephalexin, amoxicillin-clavulanate; clindamycin/doxycycline for MRSA) if cellulitis", "Abscess: incision and drainage by elevating the nail fold; partial nail avulsion if subungual pus", "Herpetic whitlow — antivirals, do not incise"]),
 ("Management of chronic paronychia.", ["Avoid wet work and irritants; cotton-lined rubber gloves; keep hands dry; don't push back cuticles", "Topical potent steroid (± antifungal) as first line (inflammatory/eczematous mechanism), tacrolimus; topical azoles/thymol 4% in alcohol for Candida", "Oral itraconazole/fluconazole when Candida is confirmed and extensive", "Refractory: intralesional steroids, en bloc excision of proximal nail fold (eponychial marsupialisation)", "Patch test if allergic contact dermatitis suspected"]),
 ("Discuss ingrown toenails and their management (PYQ).", ["Onychocryptosis — lateral nail plate embeds into lateral nail fold of great toe: tight shoes, improper trimming (curved cut), hyperhidrosis, trauma, retinoids; stages — inflammation, abscess/granulation, chronic hypertrophy of fold", "Conservative: proper nail cutting (straight across), cotton wisp/dental floss under corner, gutter splint, taping, warm soaks, topical steroid/antibiotic", "Surgical: partial nail avulsion with lateral matricectomy (phenol 88% chemical matricectomy — lowest recurrence), electrocautery/laser matricectomy, wedge resection; avoid total avulsion alone"]),
 ],
 spot=["Bolstered proximal fold with lost cuticle in a wet worker — chronic paronychia", "Phenol matricectomy for ingrown toenail"]),

dict(case="Trichotillomania", src=f"{PYQ}; {IA} (Psychocutaneous disorders; hair disorders)",
 qa=[
 ("Write a note on trichotillomania (PYQ).", ["Body-focused repetitive behaviour (DSM-5 obsessive-compulsive and related disorder) — recurrent pulling of one's own hair resulting in hair loss, with repeated attempts to stop and significant distress/impairment", "Two peaks: preschool children (habit, benign, often outgrown) and adolescents/young women (chronic, psychiatric comorbidity)"]),
 ("Clinical features.", ["Bizarre, irregular-shaped patches of incomplete alopecia (often on vertex/frontoparietal of the side of the dominant hand) with hairs of varying lengths, broken stubs, no inflammation, scalp normal", "'Tonsure' pattern (Friar Tuck sign — vertex loss sparing the periphery)", "Eyebrows, eyelashes, pubic hair may be involved", "Trichophagia (eating hair) → trichobezoar (Rapunzel syndrome — tail extending into small bowel) — ask about GI symptoms", "Associated: anxiety, depression, OCD, skin picking, nail biting, ADHD"]),
 ("Trichoscopy and histopathology.", ["Trichoscopy: broken hairs at different lengths, flame hairs, V-sign (two hairs broken at the same level), tulip hairs, hook hairs, trichoptilosis (split ends), coiled hairs, black dots, haemorrhages; no exclamation-mark hairs or yellow dots (as in AA)", "Histology: increased catagen/telogen follicles, trichomalacia (distorted soft hair shafts), pigment casts, perifollicular haemorrhage, empty follicles, minimal inflammation"]),
 ("Differential diagnosis.", ["Alopecia areata (smooth patch, exclamation-mark hairs, yellow dots), tinea capitis (scaling, KOH), traction alopecia, pressure alopecia, secondary syphilis, loose anagen syndrome, hair shaft defects (monilethrix, trichorrhexis nodosa)"]),
 ("Discuss trichorrhexis nodosa (PYQ).", ["Commonest hair shaft defect: nodes (beaded swellings) where the cortex frays into brush-like fibres — 'two brooms pushed together' — hair breaks easily", "Acquired (physical/chemical trauma — combing, bleaching, straightening — proximal in Afro-textured hair, distal in others) or congenital (argininosuccinic aciduria, Menkes, trichothiodystrophy)"]),
 ("Write a short note on Menkes kinky hair (PYQ).", ["X-linked recessive ATP7A mutation — defective copper transport (low serum copper and caeruloplasmin) → pili torti (twisted flattened hair), steely brittle hypopigmented hair, pudgy cheeks, hypothermia, seizures, neurodegeneration, death in early childhood; treat early with copper histidinate injections"]),
 ("Management.", ["Non-confrontational explanation; involve parents (children); habit-reversal training (awareness, competing response) and CBT — first line", "Pharmacotherapy: N-acetylcysteine 1200–2400 mg/day (evidence in adults), SSRIs (comorbid depression/anxiety), clomipramine, olanzapine/aripiprazole (low dose), naltrexone", "Barriers: short haircut, gloves, bandana; psychiatric referral for chronic cases", "Childhood habit type often resolves spontaneously"]),
 ],
 spot=["Bizarre patch with hairs of different lengths, flame hairs and V-sign — trichotillomania", "Trichophagia → Rapunzel syndrome"]),

dict(case="Twenty-nail dystrophy (trachyonychia)", src=f"{PYQ}; {IA} (Nail disorders)",
 qa=[
 ("What is trachyonychia?", ["Roughness of the nail plate due to matrix inflammation — opalescent, rough, sandpapered nails with excessive longitudinal ridging (opaque type) or shiny nails with multiple small regular pits (shiny type); when all 20 nails are involved — 'twenty-nail dystrophy'", "Commoner in children; usually benign and self-limiting"]),
 ("Causes.", ["Idiopathic (isolated)", "Alopecia areata (most common association — especially children), lichen planus (most common histological cause), psoriasis, eczema/atopic dermatitis, ichthyosis vulgaris, IgA deficiency, vitiligo, sarcoidosis, pemphigus vulgaris, incontinentia pigmenti, selective IgA deficiency"]),
 ("Histopathology.", ["Spongiotic changes of matrix (most common — AA, eczema, idiopathic), lichenoid (LP), psoriasiform — nail matrix biopsy rarely justified because benign course and risk of scarring"]),
 ("Differential diagnosis.", ["Onychomycosis (KOH), nail psoriasis (pits are coarse/irregular, oil-drop, onycholysis), LP with pterygium, brittle nails (onychoschizia), Darier's disease (red and white longitudinal bands with V-notching), chemical damage (nail cosmetics), ageing ridges"]),
 ("Discuss nail pitting with causes (PYQ).", ["Pits = small depressions due to focal parakeratosis from the proximal matrix shed as the nail grows", "Psoriasis (coarse, deep, irregular, random), alopecia areata (fine, shallow, regular geometric grid), eczema/atopic (coarse, irregular, with transverse ridging), lichen planus, Reiter's/reactive arthritis, pityriasis rosea, secondary syphilis, sarcoidosis, normal individuals (a few pits)", "Rosenau's depressions (larger pits — psoriasis)"]),
 ("Enumerate skin diseases with nail changes (PYQ).", ["Psoriasis (pits, oil-drop, onycholysis, subungual hyperkeratosis, splinters), LP (pterygium, thinning, ridging), AA (pits, trachyonychia), eczema (pits, Beau's lines, shiny nails from rubbing), Darier's (red–white bands, V-nicks), pemphigus (paronychia, onychomadesis), EB (dystrophy/anonychia), SJS/TEN (shedding), DM (cuticular changes), SLE (red lunulae, periungual erythema), SSc (pterygium inversum, ulcers), yellow nail syndrome, pachyonychia congenita, nail–patella syndrome (triangular lunulae, absent patella, iliac horns, nephropathy)"]),
 ("Treatment.", ["Reassurance — spontaneous improvement over years (children especially)", "Cosmetic: nail hydration (emollients, nail oils), avoid trauma, nail lacquer", "Active treatment rarely needed: potent topical steroid ± occlusion, intralesional triamcinolone to matrix, tazarotene; systemic therapy only if associated disease needs it (JAK inhibitors improve AA nails)"]),
 ],
 spot=["Rough sandpapered ridged nails on all 20 nails of a child with AA — trachyonychia", "Fine geometric pits — AA; coarse irregular pits — psoriasis"]),

dict(case="Yellow nail syndrome", src=f"{PYQ}; {IA} (Nail disorders)",
 qa=[
 ("Write a note on yellow nail syndrome (PYQ).", ["Rare disorder with the triad: yellow slow-growing nails, lymphoedema (usually lower limbs) and respiratory involvement (pleural effusion, bronchiectasis, chronic sinusitis, recurrent bronchitis/pneumonia) — two of three features enough for diagnosis", "Adults (median ~50 y); impaired lymphatic drainage (functional lymphatic abnormality) with microvasculopathy"]),
 ("Describe the nail changes.", ["Diffusely yellow to yellow-green thickened nails, increased transverse and longitudinal curvature (overcurved), loss of cuticle, absent lunula, onycholysis, very slow growth (<0.25 mm/week; normal ~0.5–1.2 mm), onychomadesis; all 20 nails often affected"]),
 ("Associations.", ["Malignancies (lung, breast, lymphoma), autoimmune disease (RA, thyroid), immunodeficiency, nephrotic syndrome, AIDS, drugs (penicillamine, bucillamine, gold, titanium dental implants/joint prostheses — titanium exposure hypothesis)"]),
 ("Differential diagnosis of yellow nails.", ["Onychomycosis (KOH/culture), psoriasis, ageing, nicotine staining (proximal spared), carotenaemia (skin also yellow), tetracycline/ antimalarial pigmentation, jaundice (sclera), pachyonychia congenita, nail varnish staining, diabetes (yellowish nails)"]),
 ("Investigations.", ["Chest X-ray/HRCT, pleural fluid analysis (exudative, lymphocytic, sometimes chylous), sinus imaging, lymphoscintigraphy, nail clipping KOH/culture, screen for associated malignancy/autoimmunity"]),
 ("Treatment.", ["Nails: oral vitamin E (α-tocopherol 800–1200 IU/day) ± oral itraconazole/fluconazole pulse (increase nail growth), zinc, topical vitamin E; nails may improve spontaneously (~30%)", "Lymphoedema: compression, physiotherapy, skin care", "Respiratory: pleurodesis/decortication for recurrent effusions, antibiotics and physiotherapy for bronchiectasis; octreotide (chylous effusions)", "Remove titanium implants if implicated"]),
 ],
 spot=["Yellow overcurved slow-growing nails + lymphoedema + pleural effusion — yellow nail syndrome", "Vitamin E + itraconazole"]),

dict(case="Androgenetic alopecia", src=f"{PYQ}; {IA} (Androgenetic alopecia); Hamilton–Norwood and Ludwig classifications",
 qa=[
 ("Define androgenetic alopecia (AGA).", ["Common, genetically determined, androgen-dependent, progressive non-scarring hair loss characterised by follicular miniaturisation in a patterned distribution; male pattern hair loss (MPHL) and female pattern hair loss (FPHL)"]),
 ("Explain the pathogenesis.", ["Genetic susceptibility (polygenic — androgen receptor gene on X chromosome, chromosome 20p11) + androgens: testosterone converted by 5α-reductase type 2 (outer root sheath/dermal papilla) to DHT → binds androgen receptors in dermal papilla of susceptible follicles → shortening of anagen and progressive miniaturisation (terminal → vellus-like), increased telogen; perifollicular micro-inflammation and fibrosis", "Occipital follicles are androgen-insensitive — basis for hair transplantation (donor dominance)", "FPHL: less clearly androgen-dependent; hyperandrogenism in some (PCOS)"]),
 ("Discuss classifications (PYQ: AGA with a note on…).", ["Men: Hamilton–Norwood (I–VII; frontotemporal recession and vertex thinning; type A variant), BASP classification", "Women: Ludwig (I–III diffuse thinning of crown with preserved frontal hairline), Olsen ('Christmas tree' pattern — frontal accentuation), Sinclair (1–5) visual scale; Savin scale"]),
 ("Clinical features.", ["MPHL: onset after puberty; bitemporal recession and vertex thinning progressing to bald crown with retained occipital/parietal fringe", "FPHL: diffuse thinning over crown and widening of central parting with intact frontal hairline; may begin at puberty or menopause", "Signs of hyperandrogenism in women: hirsutism, acne, irregular menses, AN (SAHA syndrome — Seborrhoea, Acne, Hirsutism, Alopecia)"]),
 ("Trichoscopy.", ["Hair shaft diameter diversity >20% (key sign), increased vellus hairs, perifollicular brown halo (peripilar sign), yellow dots (few), single-hair follicular units, frontal > occipital difference (useful in FPHL)"]),
 ("Discuss evaluation of hair loss (PYQ).", ["History: onset, duration, pattern, shedding vs thinning, family history, diet, drugs, illness/surgery 2–3 months before, menstrual/obstetric history, hair care practices", "Examination: pattern, scalp (scarring, scaling, erythema), hair pull test (>6 hairs/10% = active shedding), hair density, trichoscopy, signs of hyperandrogenism, nails, body hair", "Investigations: CBC, ferritin (aim >40–70 ng/ml), TSH, vitamin D, B12, zinc; women with hyperandrogenism — total/free testosterone, DHEAS, prolactin, 17-OH progesterone, pelvic USG; trichogram, biopsy (horizontal sections — terminal:vellus ratio <4:1 in AGA vs 7:1 normal) when doubtful"]),
 ("Discuss drugs used in AGA including anti-androgens (PYQ).", ["Topical minoxidil 5% (men), 2–5% (women) twice daily or foam — prolongs anagen, increases follicle size (potassium channel opener, vasodilator); initial shedding at 2–8 weeks; results at 4–6 months; must continue", "Oral finasteride 1 mg/day (men) — 5α-reductase type 2 inhibitor, reduces scalp DHT ~60%; side effects — sexual dysfunction (low libido, erectile dysfunction ~1–2%), gynaecomastia, depression (post-finasteride syndrome debated), lowers PSA by ~50%; teratogenic to male fetus (women of child-bearing age must not take/handle broken tablets)", "Dutasteride 0.5 mg (types 1 and 2 inhibitor; more potent) — oral or mesotherapy", "Topical finasteride 0.25% spray (lower systemic exposure)", "Low-dose oral minoxidil 0.25–5 mg/day (men and women) — side effects hypertrichosis, pedal oedema, tachycardia, postural hypotension", "Women: spironolactone 50–200 mg/day, cyproterone acetate (with ethinyl oestradiol), flutamide/bicalutamide (hepatotoxicity monitoring), OCP with anti-androgenic progestins; finasteride/dutasteride only in post-menopausal women", "Adjuncts: PRP injections, microneedling (with minoxidil), low-level laser therapy (LLLT), ketoconazole 2% shampoo, nutritional correction (iron, vitamin D)", "Hair transplantation: follicular unit transplantation (strip/FUT) or follicular unit extraction (FUE) — for stable disease, adequate donor area; continue medical therapy", "Camouflage: scalp micropigmentation, fibres, wigs"]),
 ("Discuss the effects of drugs on hair (PYQ).", ["Drug-induced hair loss: anagen effluvium (chemotherapy — cyclophosphamide, doxorubicin, taxanes; within 1–4 weeks), telogen effluvium (retinoids, anticoagulants — heparin, warfarin; β-blockers, ACE inhibitors, antithyroids, anticonvulsants — valproate, lithium, OCP withdrawal, interferons, statins)", "Drug-induced hypertrichosis/hirsutism: minoxidil, cyclosporine, phenytoin, diazoxide, streptomycin, steroids, danazol, testosterone, latanoprost (eyelashes), EGFR inhibitors (trichomegaly)", "Hair colour change: chloroquine (bleaching), tyrosine kinase inhibitors (imatinib — depigmentation; or darkening), PD-1 inhibitors; curling with retinoids/EGFR inhibitors"]),
 ("Prognosis.", ["Progressive without treatment; early treatment preserves rather than fully restores; effect lost within months of stopping"]),
 ],
 spot=["Bitemporal recession + vertex thinning, hair diameter diversity >20% — AGA", "Finasteride 1 mg + minoxidil 5% — men; spironolactone/minoxidil — women"]),

dict(case="Telogen effluvium", src=f"{PYQ}; {IA} (Hair loss)",
 qa=[
 ("Define telogen effluvium (TE).", ["Diffuse, non-scarring increased shedding of telogen (club) hairs occurring 2–4 months after a triggering event that pushes many anagen follicles prematurely into telogen; commonest cause of diffuse hair loss in women"]),
 ("Describe the causes and types (PYQ).", ["Acute TE (<6 months): high fever (typhoid, dengue, malaria, COVID-19), major surgery, childbirth (post-partum TE — 2–4 months after delivery), crash dieting/protein deficiency, severe emotional stress, haemorrhage, stopping OCPs, drugs (retinoids, anticoagulants, β-blockers, antithyroid, anticonvulsants)", "Chronic TE (>6 months): iron deficiency, thyroid disease, malnutrition (zinc, protein, vitamin D, biotin rarely), chronic illness (SLE, renal/hepatic failure, HIV), idiopathic chronic TE in middle-aged women (thick hair initially)", "Headington's functional types: immediate anagen release, delayed anagen release (post-partum), short anagen, immediate telogen release (minoxidil initiation), delayed telogen release"]),
 ("Clinical features.", ["Sudden increase in hair fall (handfuls while combing/washing) with diffuse thinning, especially bitemporal recession; hair pull test positive (>10% club hairs) all over scalp; no scarring, normal scalp", "Club hairs with depigmented bulb seen on pull test"]),
 ("Write a short note on anagen effluvium (PYQ).", ["Abrupt cessation of mitotic activity in anagen follicles → tapered, fractured dystrophic hairs shed within days–weeks (1–4 weeks) of insult; ~80–90% of scalp hair lost", "Causes: chemotherapy (commonest), radiation, thallium/arsenic/mercury poisoning, boric acid, colchicine overdose, severe AA, pemphigus, protein malnutrition (kwashiorkor)", "Usually reversible; regrowth may differ in colour/texture; scalp cooling reduces chemotherapy-induced alopecia; topical minoxidil may speed regrowth"]),
 ("How do you differentiate TE, AGA and diffuse AA?", ["TE: sudden shedding after trigger, positive pull test diffusely, uniform hair diameter on trichoscopy, many empty follicles/upright regrowing hairs, frontal ≈ occipital density", "AGA: gradual thinning, pattern distribution, hair diameter diversity >20%, frontal < occipital density, pull test usually negative", "Diffuse AA: rapid diffuse loss, exclamation-mark hairs, yellow and black dots, dystrophic anagen hairs on pull test"]),
 ("Investigations.", ["Detailed history of triggers 2–4 months earlier; hair pull test, trichogram (telogen >20–25%), trichoscopy", "CBC, serum ferritin, TSH/free T4, vitamin D, B12, zinc, protein/albumin, LFT/RFT, ANA if indicated, VDRL (if moth-eaten), hormonal profile if signs of hyperandrogenism; biopsy for chronic TE vs early AGA"]),
 ("Management.", ["Identify and remove/correct the trigger; reassurance — acute TE recovers in 3–6 months; cosmetic improvement takes 12–18 months", "Correct deficiencies: iron (ferritin), vitamin D, protein-rich diet; treat thyroid disease", "Topical minoxidil 2–5% may shorten duration (initial shedding); avoid harsh hair treatments", "Chronic TE: counselling (stable hair density over time), minoxidil, low-dose oral minoxidil"]),
 ],
 spot=["Diffuse shedding 3 months after typhoid/childbirth, positive pull test — telogen effluvium", "Anagen effluvium — chemotherapy, within weeks"]),
]
